package com.cursedtides.client;

import com.cursedtides.entity.ShipEntity;
import net.minecraft.client.model.ModelData;
import net.minecraft.client.model.ModelPart;
import net.minecraft.client.model.ModelPartBuilder;
import net.minecraft.client.model.ModelPartData;
import net.minecraft.client.model.ModelTransform;
import net.minecraft.client.model.TexturedModelData;
import net.minecraft.client.render.VertexConsumer;
import net.minecraft.client.render.entity.model.EntityModel;
import net.minecraft.client.util.math.MatrixStack;

/**
 * Single-masted ship built from boxes. Generated by make_ship.py together with the
 * textures, so the UV layout always matches. Bigger classes render it scaled up.
 */
public class ShipModel extends EntityModel<ShipEntity> {
    private final ModelPart root;
    private final ModelPart sail;
    private final ModelPart mast;
    private final ModelPart yard;
    private final ModelPart flag;

    public ShipModel(ModelPart root) {
        this.root = root;
        this.sail = root.getChild("sail");
        this.mast = root.getChild("mast");
        this.yard = root.getChild("yard");
        this.flag = root.getChild("flag");
    }

    /** Hide the painted pennant while a custom flag is drawn in its place. */
    public void setCustomFlag(boolean custom) {
        this.flag.visible = !custom;
    }

    /** An extra mast with its yard and canvas, for two- and three-masted ships. */
    public void renderRig(MatrixStack matrices, VertexConsumer vertices, int light, int overlay, int sailColor) {
        this.mast.render(matrices, vertices, light, overlay, 0xFFFFFFFF);
        this.yard.render(matrices, vertices, light, overlay, 0xFFFFFFFF);
        if (this.sail.visible) this.sail.render(matrices, vertices, light, overlay, sailColor);
    }

    /** Just the flag box, drawn with a flag texture laid out on the same UVs. */
    public void renderFlag(MatrixStack matrices, VertexConsumer vertices, int light, int overlay) {
        boolean was = this.flag.visible;
        this.flag.visible = true;
        this.flag.render(matrices, vertices, light, overlay, 0xFFFFFFFF);
        this.flag.visible = was;
    }

    public static TexturedModelData getTexturedModelData() {
        ModelData data = new ModelData();
        ModelPartData root = data.getRoot();
        root.addChild("keel", ModelPartBuilder.create().uv(0, 0).cuboid(-10f, 0f, -26f, 20f, 3f, 52f), ModelTransform.NONE);
        root.addChild("side_left", ModelPartBuilder.create().uv(144, 0).cuboid(-12f, -10f, -26f, 2f, 13f, 52f), ModelTransform.NONE);
        root.addChild("side_right", ModelPartBuilder.create().uv(0, 65).cuboid(10f, -10f, -26f, 2f, 13f, 52f), ModelTransform.NONE);
        root.addChild("stern", ModelPartBuilder.create().uv(108, 65).cuboid(-12f, -10f, -28f, 24f, 13f, 2f), ModelTransform.NONE);
        root.addChild("bow", ModelPartBuilder.create().uv(160, 65).cuboid(-8f, -10f, 26f, 16f, 13f, 6f), ModelTransform.NONE);
        root.addChild("bow_tip", ModelPartBuilder.create().uv(204, 65).cuboid(-4f, -9f, 32f, 8f, 11f, 5f), ModelTransform.NONE);
        root.addChild("deck", ModelPartBuilder.create().uv(0, 130).cuboid(-10f, -4f, -26f, 20f, 1f, 52f), ModelTransform.NONE);
        root.addChild("rail_left", ModelPartBuilder.create().uv(144, 130).cuboid(-12f, -12f, -26f, 2f, 2f, 52f), ModelTransform.NONE);
        root.addChild("rail_right", ModelPartBuilder.create().uv(0, 184).cuboid(10f, -12f, -26f, 2f, 2f, 52f), ModelTransform.NONE);
        root.addChild("cabin", ModelPartBuilder.create().uv(108, 184).cuboid(-9f, -12f, -26f, 18f, 8f, 10f), ModelTransform.NONE);
        root.addChild("cabin_roof", ModelPartBuilder.create().uv(164, 184).cuboid(-10f, -13f, -27f, 20f, 1f, 12f), ModelTransform.NONE);
        root.addChild("mast", ModelPartBuilder.create().uv(228, 184).cuboid(-1f, -80f, 4f, 2f, 76f, 2f), ModelTransform.NONE);
        root.addChild("yard", ModelPartBuilder.create().uv(0, 262).cuboid(-20f, -68f, 3f, 40f, 2f, 2f), ModelTransform.NONE);
        root.addChild("bowsprit", ModelPartBuilder.create().uv(84, 262).cuboid(-1f, -12f, 36f, 2f, 2f, 16f), ModelTransform.NONE);
        root.addChild("flag", ModelPartBuilder.create().uv(120, 262).cuboid(0f, -80f, -6f, 1f, 6f, 10f), ModelTransform.NONE);
        root.addChild("cannon_l1", ModelPartBuilder.create().uv(142, 262).cuboid(-14f, -8f, -10f, 2f, 2f, 4f), ModelTransform.NONE);
        root.addChild("cannon_l2", ModelPartBuilder.create().uv(154, 262).cuboid(-14f, -8f, 8f, 2f, 2f, 4f), ModelTransform.NONE);
        root.addChild("cannon_r1", ModelPartBuilder.create().uv(166, 262).cuboid(12f, -8f, -10f, 2f, 2f, 4f), ModelTransform.NONE);
        root.addChild("cannon_r2", ModelPartBuilder.create().uv(178, 262).cuboid(12f, -8f, 8f, 2f, 2f, 4f), ModelTransform.NONE);
        root.addChild("sail", ModelPartBuilder.create().uv(0, 280).cuboid(-18f, 0f, 6f, 36f, 40f, 1f).uv(74, 280).cuboid(0f, 16f, 14f, 1f, 36f, 20f), ModelTransform.pivot(0.0f, -66.0f, 0.0f));
        return TexturedModelData.of(data, 256, 512);
    }

    @Override
    public void setAngles(ShipEntity ship, float limbAngle, float limbDistance, float animationProgress,
                          float headYaw, float headPitch) {
        int setting = ship.getSail();
        this.sail.visible = setting > 0;
        this.sail.yScale = setting == 1 ? 0.5f : 1.0f;
        // A little belly in the canvas when the wind is behind her
        this.sail.pitch = setting > 0 ? -0.06f : 0.0f;
    }

    @Override
    public void render(MatrixStack matrices, VertexConsumer vertices, int light, int overlay, int color) {
        this.root.render(matrices, vertices, light, overlay, color);
    }

    /** Everything but the canvas, in natural colours. */
    public void renderHull(MatrixStack matrices, VertexConsumer vertices, int light, int overlay) {
        boolean wasVisible = this.sail.visible;
        this.sail.visible = false;
        this.root.render(matrices, vertices, light, overlay, 0xFFFFFFFF);
        this.sail.visible = wasVisible;
    }

    /** Just the canvas, tinted (0xAARRGGBB). */
    public void renderSail(MatrixStack matrices, VertexConsumer vertices, int light, int overlay, int color) {
        if (this.sail.visible) {
            this.sail.render(matrices, vertices, light, overlay, color);
        }
    }
}
